// Step 3 - 80x30 color text mode over HDMI
//
// The screen content starts from screen.hex (generated by tools/gen_screen.py):
// a title bar, the full character set, the palette and some sample text.
// To show that the character RAM can be changed while the picture is being
// displayed, a small writer updates an 8-digit hex frame counter on the
// screen every frame through the RAM's write port. Later the CPU will use the
// same write port.
//
//   video_timing --> text_mode --> hdmi_out
//                       ^
//          frame counter writer (wr_en / wr_addr / wr_data)
//
// LEDs: led[5] = PLL locked, led[0] = blinks once per second
// S1 = reset (the counter restarts from 0; the rest of the text stays,
// because a reset doesn't reload block RAM - only reprogramming does)

module top (
    input  wire       clk,          // 27 MHz
    input  wire       btn1,         // S1, active low
    output wire [5:0] led,          // active low
    output wire       tmds_clk_p,
    output wire       tmds_clk_n,
    output wire [2:0] tmds_d_p,
    output wire [2:0] tmds_d_n
);

    // Screen position of the frame counter; must match tools/gen_screen.py
    localparam FRAME_ROW = 26;
    localparam FRAME_COL = 30;
    localparam [11:0] FRAME_ADDR = FRAME_ROW * 80 + FRAME_COL;
    localparam [7:0]  FRAME_ATTR = 8'h0E;      // bg 0 (black), fg 14 (yellow)

    // ---- Clocks and reset (same as step 2) -------------------------------
    wire clk_tmds, clk_pix, lock;

    clocks clocks_i (.clk_27(clk), .clk_tmds(clk_tmds), .clk_pix(clk_pix), .lock(lock));

    wire rst_async = !btn1 || !lock;
    reg [1:0] rst_sync = 2'b11;
    always @(posedge clk_pix or posedge rst_async)
        if (rst_async) rst_sync <= 2'b11;
        else           rst_sync <= {rst_sync[0], 1'b0};
    wire rst = rst_sync[1];

    // ---- Timing ---------------------------------------------------------
    wire       hsync, vsync, de, frame_start;
    wire [9:0] x, y;

    video_timing timing (
        .clk(clk_pix), .rst(rst),
        .hsync(hsync), .vsync(vsync), .de(de),
        .x(x), .y(y), .frame_start(frame_start)
    );

    // ---- Frame counter writer -------------------------------------------
    // On each frame_start: take a snapshot of the counter, then write its 8
    // hex digits into the character RAM, one per clock (8 clocks in total).
    reg [31:0] frame_count = 0;
    reg [31:0] snapshot    = 0;
    reg [3:0]  digit       = 8;     // 0..7 = writing that digit, 8 = idle

    // 4-bit value -> ASCII code of its hex digit
    function [7:0] hex_char(input [3:0] n);
        hex_char = (n < 10) ? 8'h30 + n : 8'h41 + (n - 10);   // '0'.. or 'A'..
    endfunction

    always @(posedge clk_pix) begin
        if (rst) begin
            frame_count <= 0;
            digit       <= 8;
        end else if (frame_start) begin
            snapshot    <= frame_count;
            frame_count <= frame_count + 1;
            digit       <= 0;
        end else if (digit != 8) begin
            digit <= digit + 1'b1;
        end
    end

    // Digit 0 is the leftmost (most significant) one
    wire [3:0]  nibble  = snapshot[31 - digit[2:0]*4 -: 4];
    wire        wr_en   = (digit != 8);
    wire [11:0] wr_addr = FRAME_ADDR + digit[2:0];
    wire [15:0] wr_data = {FRAME_ATTR, hex_char(nibble)};

    // ---- Text mode renderer ---------------------------------------------
    wire [23:0] rgb;
    wire        de_t, hsync_t, vsync_t;

    text_mode #(.FONT_FILE("font.hex"), .SCREEN_FILE("screen.hex")) text (
        .clk(clk_pix),
        .x(x), .y(y), .de(de), .hsync(hsync), .vsync(vsync),
        .wr_clk(clk_pix), .wr_en(wr_en), .wr_addr(wr_addr), .wr_data(wr_data), .scroll(6'd0),
        .rgb(rgb), .de_o(de_t), .hsync_o(hsync_t), .vsync_o(vsync_t)
    );

    // ---- HDMI output ----------------------------------------------------
    hdmi_out hdmi (
        .clk_pix(clk_pix), .clk_tmds(clk_tmds), .rst(rst),
        .r(rgb[23:16]), .g(rgb[15:8]), .b(rgb[7:0]),
        .hsync(hsync_t), .vsync(vsync_t), .de(de_t),
        .tmds_clk_p(tmds_clk_p), .tmds_clk_n(tmds_clk_n),
        .tmds_d_p(tmds_d_p), .tmds_d_n(tmds_d_n)
    );

    // ---- LEDs -----------------------------------------------------------
    // Bit 5 of the frame counter flips every 32 frames (~0.53 s)
    assign led = ~{lock, 4'b0000, frame_count[5]};

endmodule
